const languageParameter = new URLSearchParams(location.search).get('lang');
let portfolioLanguage = 'zh';
try { portfolioLanguage = languageParameter === 'en' || languageParameter === 'zh' ? languageParameter : localStorage.getItem('portfolioLanguage') === 'en' ? 'en' : 'zh'; } catch { portfolioLanguage = languageParameter === 'en' ? 'en' : 'zh'; }
const originalText = new WeakMap();
const originalAttributes = new WeakMap();
const translationFragments = Object.keys(PORTFOLIO_DICTIONARY).filter(k=>k.length<46).sort((a,b)=>b.length-a.length);
const fragmentPattern = new RegExp(translationFragments.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
function portfolioTranslate(text) {
 const leading=text.match(/^\s*/)[0], trailing=text.match(/\s*$/)[0], core=text.trim();
 if(!core)return text;
 if(Object.prototype.hasOwnProperty.call(PORTFOLIO_DICTIONARY,core))return leading+PORTFOLIO_DICTIONARY[core]+trailing;
 let result=core.replace(/(\d+) 份原始文件/g,(_,n)=>`${n} original file${n==='1'?'':'s'}`)
  .replace(/(\d+) 份材料/g,(_,n)=>`${n} file${n==='1'?'':'s'}`)
  .replace(/(\d+) 个项目/g,(_,n)=>`${n} project${n==='1'?'':'s'}`);
 result=result.replace(fragmentPattern,key=>PORTFOLIO_DICTIONARY[key]);
 return leading+result+trailing;
}
function portfolioEnglishSearch(project) {
 const e=PORTFOLIO_PROJECT_EN[project.id];
 return [e?JSON.stringify(e):'',...project.topics.map(portfolioTranslate),portfolioTranslate(project.category),portfolioTranslate(project.kind),...projectMeta(project).methods.map(portfolioTranslate),...project.files.map(f=>portfolioTranslate(f.label))].join(' ');
}
const languageSwitch=document.createElement('nav');
languageSwitch.id='language-switch';languageSwitch.className='language-switch';languageSwitch.setAttribute('aria-label','Language / 语言');
languageSwitch.innerHTML='<button type="button" data-language="zh" lang="zh-CN">中文</button><button type="button" data-language="en" lang="en">EN</button>';
document.querySelector('.topbar').appendChild(languageSwitch);
const excludedTranslation = el => el?.closest('script,style,noscript,#preview-body,#language-switch,.file-info small');
let translationObserver;
function applyPortfolioLanguage() {
 translationObserver?.disconnect();
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let node;
 while(node=walker.nextNode()) {
  if(excludedTranslation(node.parentElement))continue;
  let saved=originalText.get(node);
  if(!saved||(node.nodeValue!==saved.zh&&node.nodeValue!==saved.en)){
   saved={zh:node.nodeValue,en:portfolioTranslate(node.nodeValue)};originalText.set(node,saved);
  }
  const value=portfolioLanguage==='en'?saved.en:saved.zh;
  if(node.nodeValue!==value)node.nodeValue=value;
 }
 document.querySelectorAll('[aria-label],[placeholder],[alt],[title]').forEach(el=>{
  if(excludedTranslation(el))return;
  let saved=originalAttributes.get(el);if(!saved){saved={};originalAttributes.set(el,saved)}
  for(const attr of ['aria-label','placeholder','alt','title']) {
   const value=el.getAttribute(attr);if(value===null)continue;
   if(!saved[attr]||(value!==saved[attr].zh&&value!==saved[attr].en))saved[attr]={zh:value,en:portfolioTranslate(value)};
   const translated=portfolioLanguage==='en'?saved[attr].en:saved[attr].zh;
   if(value!==translated)el.setAttribute(attr,translated);
  }
 });
 document.documentElement.lang=portfolioLanguage==='en'?'en':'zh-CN';
 document.documentElement.dataset.language=portfolioLanguage;
 document.title=portfolioLanguage==='en'?'Jingwei Liu · Project Archive':'Jingwei Liu · 项目档案';
 document.querySelector('meta[name="description"]').content=portfolioLanguage==='en'?'Jingwei Liu’s portfolio of accounting, financial analysis, research and consulting projects.':'刘婧玮的会计、财务分析与研究项目档案。';
 languageSwitch.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===portfolioLanguage)));
 translationObserver?.observe(document.body,{subtree:true,childList:true,characterData:true});
}
function setPortfolioLanguage(language) {
 if(language!=='zh'&&language!=='en')return;
 portfolioLanguage=language;
 try{localStorage.setItem('portfolioLanguage',language)}catch{}
 const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url.pathname+url.search+url.hash);
 applyPortfolioLanguage();
}
languageSwitch.querySelectorAll('button').forEach(b=>b.onclick=()=>setPortfolioLanguage(b.dataset.language));
translationObserver=new MutationObserver(()=>applyPortfolioLanguage());
applyPortfolioLanguage();
